INSERT INTO "public"."pub_quiz_questions" ("id", "difficulty", "question", "options", "correct_index") VALUES (1, 'easy', 'What is the capital city of Wales?', '["Edinburgh","Belfast","Cardiff","Manchester"]', 2), (2, 'easy', 'Which currency is used in the UK?', '["Euro","Pound Sterling","Dollar","Franc"]', 1), (3, 'easy', 'What color are traditional double-decker buses in London?', '["Blue","Yellow","Red","Green"]', 2), (4, 'easy', 'What does the common British word ''Bloke'' mean?', '["A man / guy","A domestic dog","A wallet","A slice of cake"]', 0), (5, 'easy', 'What does the popular British slang term ''Quid'' refer to?', '["British Pound (currency)","A quick snack","A round of drinks","An umbrella"]', 0), (6, 'easy', 'Which of these is a famous British royal residence in London?', '["Buckingham Palace","The White House","Versailles","Eiffel Tower"]', 0), (7, 'easy', 'What is the national flower of England?', '["Rose","Tulip","Daffodil","Thistle"]', 0), (8, 'easy', 'Which ocean borders the United Kingdom to the west?', '["Pacific Ocean","Indian Ocean","Atlantic Ocean","Arctic Ocean"]', 2), (9, 'easy', 'What is a traditional British "cuppa"?', '["A cup of tea","A cup of coffee","A bowl of soup","A pint of cider"]', 0), (10, 'easy', 'Which iconic clock tower in London is commonly known as Big Ben?', '["The Shard","Elizabeth Tower","St. Paul''s Cathedral","Tower Bridge"]', 1), (11, 'medium', 'What is the traditional British term for cask-conditioned draft ale served at cellar temperature?', '["Stout","Real Ale","Craft Lager","Cider"]', 1), (12, 'medium', 'What does the British slang phrase ''Having a chinwag'' mean?', '["Arguing over the bar bill","Chugging a pint in one breath","Having a chat / gossiping","Falling asleep in a pub armchair"]', 2), (13, 'medium', 'In what year did the iconic London Eye officially open to the public?', '["1995","2000","2005","1988"]', 1), (14, 'medium', 'Which dish is widely considered Britain''s unofficial national pub dish?', '["Chicken Tikka Masala","Beef Wellington","Shepherd''s Pie","Full English Breakfast"]', 0), (15, 'medium', 'What do you do when you hear the call ''Last orders!'' in a pub?', '["Ask for a free round of drinks","Place your final drink order before the bar closes","Leave the premises immediately","Pay the bill for the entire table"]', 1), (16, 'medium', 'Which British band released the legendary album "Abbey Road" in 1969?', '["The Rolling Stones","The Beatles","Queen","Led Zeppelin"]', 1), (17, 'medium', 'What is the name of the traditional British cake served at teatime with dried fruit?', '["Cheesecake","Victoria Sponge","Battenberg cake","Brownie"]', 1), (18, 'medium', 'Which river flows through the heart of London?', '["River Severn","River Thames","River Clyde","River Trent"]', 1), (19, 'medium', 'What does the British slang word "Kip" mean?', '["A short sleep / nap","A heavy winter coat","A fast car","A type of beer glass"]', 0), (20, 'medium', 'What is a "pub landlord" responsible for?', '["Owning or running the public house","Checking IDs at the door","Brewing the beer in the basement","Cleaning the tables exclusively"]', 0), (21, 'hard', 'What is the name of the iconic London pub where the Gunpowder Plot conspirators allegedly met?', '["The Lamb & Flag","The Crown & Sceptre","Ye Olde Cheshire Cheese","The Black Friar"]', 0), (22, 'hard', 'Which British monarch reigned the longest before Queen Elizabeth II?', '["King Henry VIII","Queen Victoria","King George III","Queen Elizabeth I"]', 1), (23, 'hard', 'Which historic UK monument is a prehistoric stone circle in Wiltshire?', '["Tower of London","Stonehenge","Hadrian''s Wall","Edinburgh Castle"]', 1), (24, 'hard', 'What is the highest mountain in the United Kingdom?', '["Snowdon","Scafell Pike","Ben Nevis","Slieve Donard"]', 2), (25, 'hard', 'Which British scientist formulated the theory of evolution by natural selection?', '["Isaac Newton","Stephen Hawking","Charles Darwin","Alexander Fleming"]', 2), (26, 'hard', 'In which English city would you find the oldest university in the English-speaking world?', '["London","Cambridge","Oxford","Bristol"]', 2), (27, 'hard', 'What year was the Great Fire of London, which destroyed much of the medieval city?', '["1066","1666","1815","1914"]', 1), (28, 'hard', 'Which famous British Prime Minister during WWII was awarded the Nobel Prize in Literature?', '["Neville Chamberlain","Winston Churchill","Clement Attlee","David Lloyd George"]', 1), (29, 'hard', 'What is the name of the traditional Scottish instrument played with a bag and pipes?', '["Fiddle","Bodhrán","Great Highland Bagpipe","Accordion"]', 2), (30, 'hard', 'Which treaty officially united the Kingdom of England and the Kingdom of Scotland in 1707?', '["Treaty of Utrecht","Treaty of Westminster","Acts of Union","Treaty of London"]', 2);